#!/usr/bin/env bash
#
# tier-set -- /tier backend (S4, claude-orca-3sk.4). Binds the model tier by
# writing .claude-dev/run/tier.json {top, worker, recon, pinned, overdrive,
# updated} and .model in <config dir>/settings.local.json -- NEVER
# agents/*.md: the config dir is regenerated by config-sync, so the binding
# lives in hook-read state instead of frontmatter (the superseded design:
# attachments/claude_docker/scripts/tier-set.sh rewrote executor.md/scout.md
# directly). tier-gate (PreToolUse[Agent]) reads tier.json to inject the
# worker/recon model into executor/scout spawns that omit one;
# tier-prime/tier-reconcile also read/write it.
#
# Usage:
#   tier-set                           # no args -> show (same as `show`)
#   tier-set show                      # the bound trio + the explanation
#   tier-set help                      # the explanation alone
#   tier-set <top>                     # worker/recon auto-derived (capped)
#   tier-set <top> <worker> [<recon>]  # explicit pin
#   tier-set overdrive                 # lift the worker cap on the bound top
#   tier-set <role> <spec>             # rebind ONE role's backend+agent+model
#
# v2 (claude-orca-qa2.12): <role> is worker|recon|checker and <spec> is one of
#   openrouter:<vendor/model>   -> backend orca,     agent opencode
#   claude:[<alias|id>]         -> backend orca,     agent claude
#   codex:<id> | gemini:<id>    -> backend orca,     agent codex|gemini
#   orca | subagent             -> that backend,     agent claude, derived model
#   <alias|id> | inherit        -> backend subagent, agent claude
# A spec that names a model pins THAT role (tier-reconcile stops re-deriving
# its model); the derived forms leave it tracking the ladder. On a plain
# `tier-set <top>` all three roles are rebound to the defaults: worker =
# orca+claude when the Orca runtime answers `status --json` (2s probe), else
# subagent; recon = subagent; checker = subagent+inherit. See
# scripts/lib/tier-roles.sh for the on-disk shape and the v1 read rule.
#
# Ladder and derivation: scripts/tier-derive.sh (ported unchanged from the
# old template) is the single source of truth; this script never repeats it.
#
# TIER_STATE_FILE / TIER_SETTINGS_LOCAL override the paths (test suite).
# TIER_DERIVE overrides the tier-derive lookup (default: alongside this
# script, i.e. the sibling scripts/tier-derive.sh, or tier-derive on PATH).
#
# claude-orca-2j2 (claude-orca-1w8 slice A): a positional trio or a per-role
# spec may now be a PHRASE -- a short route name from
# config/delegate-routes.json (TIER_ROUTES_FILE), a bare OpenRouter
# vendor/model id, or a free-text query resolved against an OpenRouter model
# catalogue (TIER_MODELS_FILE, default <run dir>/openrouter-models.json,
# fetched from https://openrouter.ai/api/v1/models unless TIER_MODELS_FETCH=0)
# -- each optionally carrying a reasoning-effort variant as
# name@effort/name (effort)/name(effort), or a trailing bare effort word. A
# single argument containing a comma or whitespace is re-split into the trio
# before anything else runs (config/claude-commands/tier.md passes
# "$ARGUMENTS" quoted so this survives the shell). See resolve_worker_recon_
# phrase, parse_effort and catalogue_lookup below, and tier.md's
# argument-hint for the accepted forms.
#
# Deliberately dropped from the old design, out of S4's scope: probing
# candidates against a live `claude -p` round trip (unsuitable for hermetic
# tests, and not asked for here), and the `cost` subcommand (cost-mirror is
# S7). Also dropped: tier-set itself purging legacy ANTHROPIC_DEFAULT_*/
# CLAUDE_CODE_SUBAGENT_MODEL vars -- that is tier-reconcile's job now (see
# its header), so it isn't duplicated here.

set -u

# Resolve through a symlink chain (e.g. bin/tier-set -> ../scripts/tier-set.sh)
# to this script's real directory, so lib/paths.sh resolves whether this is
# invoked via the repo copy or the .claude-dev/template/bin/ symlink.
_resolve_script_path() {
    local src="${BASH_SOURCE[0]}"
    while [ -L "$src" ]; do
        local link dir
        link="$(readlink "$src")"
        case "$link" in
            /*) src="$link" ;;
            *)  dir="$(cd "$(dirname "$src")" && pwd)"; src="$dir/$link" ;;
        esac
    done
    echo "$src"
}
SCRIPT_DIR="$(cd "$(dirname "$(_resolve_script_path)")" && pwd)"
# shellcheck source=lib/paths.sh
. "$SCRIPT_DIR/lib/paths.sh"
# shellcheck source=lib/tier-roles.sh
. "$SCRIPT_DIR/lib/tier-roles.sh"

DERIVE="${TIER_DERIVE:-}"
if [ -z "$DERIVE" ]; then
    DERIVE=$(command -v tier-derive 2>/dev/null) || DERIVE="$SCRIPT_DIR/tier-derive.sh"
fi

STATE_FILE="${TIER_STATE_FILE:-}"
[ -n "$STATE_FILE" ] || STATE_FILE="$(tier_state_file 2>/dev/null)" || STATE_FILE=""

LOCAL_SETTINGS="${TIER_SETTINGS_LOCAL:-}"
[ -n "$LOCAL_SETTINGS" ] || LOCAL_SETTINGS="$(claude_config_dir)/settings.local.json"

# The route table a short worker/recon name resolves against (claude-orca-2j2).
# TIER_ROUTES_FILE overrides it; default = <repo>/config/delegate-routes.json,
# found the same way DERIVE is: via lib/paths.sh's template_dir when this is
# the repo checkout, falling back to a path relative to this script.
ROUTES_FILE="${TIER_ROUTES_FILE:-}"
if [ -z "$ROUTES_FILE" ]; then
    _tier_set_root="$(template_dir 2>/dev/null)" || _tier_set_root="$SCRIPT_DIR/.."
    ROUTES_FILE="$_tier_set_root/config/delegate-routes.json"
fi

# An alias is already the value we want: Claude Code resolves "fable",
# "opus", "sonnet" and "haiku" to the newest model of that family, so the
# bound value never has to be bumped when a new version ships. Only the
# spelling is normalised (case); a full id passes through untouched.
alias_id() {  # alias -> canonical alias; unknown strings pass through (full ids)
    case "$1" in
        fable|Fable|FABLE)    echo fable ;;
        opus|Opus|OPUS)       echo opus ;;
        sonnet|Sonnet|SONNET) echo sonnet ;;
        haiku|Haiku|HAIKU)    echo haiku ;;
        *)                    echo "$1" ;;
    esac
}

# Only safe id characters -- the same injection guard the old design used
# before writing a model id into a file; jq itself is injection-safe, but a
# typo/empty value here is still a useful UX error before we bind anything.
valid_id() {
    case "$1" in
        ''|*[!a-zA-Z0-9._\[\]-]*) return 1 ;;
        *) return 0 ;;
    esac
}

state_field() {  # state_field <field> -- '' if the file/field is absent
    [ -n "$STATE_FILE" ] && [ -f "$STATE_FILE" ] || { echo ""; return 0; }
    jq -r ".$1 // empty" "$STATE_FILE" 2>/dev/null
}

# A model REFERENCE may also carry '/' (openrouter/qwen/qwen3-coder).
valid_model_ref() {
    case "$1" in
        ''|*[!a-zA-Z0-9._/\[\]-]*) return 1 ;;
        *) return 0 ;;
    esac
}

# --- phrases and reasoning-effort variants (claude-orca-2j2) ---------------

trim() {  # trim <string> -- strips leading/trailing whitespace
    local s="$1"
    s="${s#"${s%%[![:space:]]*}"}"
    s="${s%"${s##*[![:space:]]}"}"
    printf '%s' "$s"
}

valid_effort() {
    case "$1" in
        none|minimal|low|medium|high|xhigh|max) return 0 ;;
        *) return 1 ;;
    esac
}

# parse_effort <phrase> -- prints "<name>\n<effort>" (effort line empty if
# none present, or the word was literally "none"). Recognises three forms:
# name@effort, "name (effort)"/"name(effort)" (trailing parenthetical), and a
# trailing bare word when the phrase has more than one whitespace-separated
# word (a comma-phrase carrying internal spaces, or a per-role form's joined
# 2nd+3rd token). Only @ makes an unrecognised word an ERROR -- the other two
# forms silently leave the phrase whole when the trailing bit isn't a known
# effort word (it is then just part of the name/query).
parse_effort() {
    local phrase="$1" name="" effort="" rest cand
    case "$phrase" in
        *@*)
            name="${phrase%%@*}"
            effort="${phrase#*@}"
            if ! valid_effort "$effort"; then
                echo "tier-set: unknown effort word '$effort' in '$phrase' -- want one of: none minimal low medium high xhigh max; nothing bound" >&2
                return 1
            fi
            ;;
        *")")
            rest="${phrase%)}"
            case "$rest" in
                *"("*)
                    cand="${rest##*(}"
                    if valid_effort "$cand"; then
                        name="$(trim "${rest%(*}")"
                        effort="$cand"
                    else
                        name="$phrase"
                    fi
                    ;;
                *) name="$phrase" ;;
            esac
            ;;
        *) name="$phrase" ;;
    esac
    if [ -z "$effort" ]; then
        case "$phrase" in
            *" "*)
                cand="${phrase##* }"
                if valid_effort "$cand"; then
                    name="${phrase% *}"
                    effort="$cand"
                fi
                ;;
        esac
    fi
    [ "$effort" = "none" ] && effort=""
    printf '%s\n%s\n' "$name" "$effort"
}

# write_state <top> <worker> <recon> <pinned:true|false> <overdrive:true|false>
#             [<auto-derived:true|false>]
# Writes the file whole -- v1 keys plus the v2 .roles block at its defaults
# (worker on the orca backend when the runtime answers, else subagent), so a
# plain `/tier <top>` resets every role, exactly as it resets pin/overdrive.
#
# claude-orca-qa2.20: on the AUTO-DERIVED path only ($6 = true, i.e. a plain
# `/tier <top>`), a folder that has an OpenRouter key gets the GLM worker
# instead of the claude rung -- the key decides the VENDOR (opencode running
# openrouter/z-ai/glm-5.3), the Orca probe decides only the BACKEND. An
# explicit 2/3-arg pin and `overdrive` are explicit requests for a claude
# model and are left alone. TIER_EFFECTIVE_WORKER carries the model actually
# bound back to the caller, for the message it prints.
TIER_EFFECTIVE_WORKER=""
write_state() {
    [ -n "$STATE_FILE" ] || { echo "tier-set: cannot determine the project's tier state file (not inside a bootstrapped project; set CLAUDE_ORCA_ROOT or TIER_STATE_FILE) -- nothing bound" >&2; return 1; }
    mkdir -p "$(dirname "$STATE_FILE")" 2>/dev/null
    local tmp wb wa wm ck
    wb=subagent
    tier_orca_reachable && wb=orca
    wa=claude; wm="$2"
    # The checker rung is derived like every other one (tier-derive --checker:
    # the top capped at opus), so a fable orchestrator is graded from a seat
    # that is neither its own nor the worker's. An off-ladder top has no rung
    # to grade from, and keeps the old flat "inherit" (claude-orca-8a0.2).
    ck=$("$DERIVE" --checker "$1" 2>/dev/null) || ck=""
    [ -n "$ck" ] || ck=inherit
    if [ "${6:-false}" = "true" ] && tier_openrouter_key_present; then
        wa=opencode; wm="$TIER_OPENROUTER_DEFAULT_MODEL"
    fi
    TIER_EFFECTIVE_WORKER="$wm"
    tmp=$(mktemp "$STATE_FILE.XXXXXX") || return 1
    if jq -n --arg t "$1" --arg w "$wm" --arg c "$3" --argjson p "$4" --argjson o "$5" \
          --arg wb "$wb" --arg wa "$wa" --arg ck "$ck" --arg u "$(date -u +%Y-%m-%dT%H:%M:%SZ)" \
          '{top: $t, worker: $w, recon: $c,
            roles: {worker:  {backend: $wb,       agent: $wa,      model: $w},
                    recon:   {backend: "subagent", agent: "claude", model: $c},
                    checker: {backend: "subagent", agent: "claude", model: $ck}},
            pinned: $p, overdrive: $o, updated: $u}' \
          > "$tmp" 2>/dev/null && jq -e . "$tmp" >/dev/null 2>&1; then
        mv "$tmp" "$STATE_FILE"
    else
        rm -f "$tmp"
        echo "tier-set: failed to write $STATE_FILE" >&2
        return 1
    fi
}

# write_state_v3 <top> <wb> <wa> <wm> <wv> <cb> <ca> <cm> <cv> <pinned> <overdrive>
# The phrase-aware sibling of write_state (claude-orca-2j2): the trio form
# now resolves worker/recon through resolve_worker_recon_phrase first, so
# their backend/agent/model (and an optional variant) are already decided by
# the caller -- this just writes them, plus the derived checker rung, the
# same way write_state does. Used by the 2/3-arg positional form only; the
# 1-arg auto-derive path keeps using write_state.
write_state_v3() {
    local top="$1" wb="$2" wa="$3" wm="$4" wv="$5" cb="$6" ca="$7" cm="$8" cv="$9" pinned="${10}" overdrive="${11}"
    [ -n "$STATE_FILE" ] || { echo "tier-set: cannot determine the project's tier state file (not inside a bootstrapped project; set CLAUDE_ORCA_ROOT or TIER_STATE_FILE) -- nothing bound" >&2; return 1; }
    mkdir -p "$(dirname "$STATE_FILE")" 2>/dev/null
    local ck tmp
    ck=$("$DERIVE" --checker "$top" 2>/dev/null) || ck=""
    [ -n "$ck" ] || ck=inherit
    tmp=$(mktemp "$STATE_FILE.XXXXXX") || return 1
    if jq -n --arg t "$top" \
          --arg wb "$wb" --arg wa "$wa" --arg wm "$wm" --arg wv "$wv" \
          --arg cb "$cb" --arg ca "$ca" --arg cm "$cm" --arg cv "$cv" \
          --arg ck "$ck" --argjson p "$pinned" --argjson o "$overdrive" \
          --arg u "$(date -u +%Y-%m-%dT%H:%M:%SZ)" \
          '{top: $t, worker: $wm, recon: $cm,
            roles: {
              worker:  (if $wv != "" then {backend:$wb, agent:$wa, model:$wm, pinned:true, variant:$wv}
                        else {backend:$wb, agent:$wa, model:$wm, pinned:true} end),
              recon:   (if $cv != "" then {backend:$cb, agent:$ca, model:$cm, pinned:true, variant:$cv}
                        else {backend:$cb, agent:$ca, model:$cm, pinned:true} end),
              checker: {backend:"subagent", agent:"claude", model:$ck}
            },
            pinned: $p, overdrive: $o, updated: $u}' \
          > "$tmp" 2>/dev/null && jq -e . "$tmp" >/dev/null 2>&1; then
        mv "$tmp" "$STATE_FILE"
    else
        rm -f "$tmp"
        echo "tier-set: failed to write $STATE_FILE" >&2
        return 1
    fi
}

# write_role <role> <backend> <agent> <model> <pinned:true|false> [<variant>]
# Patches ONE role into an existing tier.json, mirroring the model back into
# the v1 .worker/.recon key so every reader (including a v1-era one) agrees.
# A spec that names its own model outright (openrouter:/codex:/gemini:/an
# explicit claude:<id>) needs no bound top to make sense of, so an absent
# tier.json is not an error here -- it starts from {} and picks up a .top
# the next time a plain `/tier <top>` runs. (derived_role_model, above,
# still refuses a spec that DOES need a top -- that check runs before this
# function is ever called, so this relaxation never masks it.)
write_role() {
    [ -n "$STATE_FILE" ] || { echo "tier-set: cannot determine the project's tier state file (not inside a bootstrapped project; set CLAUDE_ORCA_ROOT or TIER_STATE_FILE) -- nothing bound" >&2; return 1; }
    mkdir -p "$(dirname "$STATE_FILE")" 2>/dev/null
    local tmp base
    base='{}'
    if [ -f "$STATE_FILE" ]; then
        base="$(cat "$STATE_FILE" 2>/dev/null)"
        printf '%s' "$base" | jq -e . >/dev/null 2>&1 || { echo "tier-set: $STATE_FILE is not valid JSON -- run /tier <top> to rebind it; nothing bound" >&2; return 1; }
    fi
    tmp=$(mktemp "$STATE_FILE.XXXXXX") || return 1
    if printf '%s' "$base" | jq --arg r "$1" --arg b "$2" --arg a "$3" --arg m "$4" --argjson p "$5" --arg v "${6:-}" \
          --arg u "$(date -u +%Y-%m-%dT%H:%M:%SZ)" \
          '.roles = ((.roles // {}) | .[$r] = (if $v != "" then {backend: $b, agent: $a, model: $m, pinned: $p, variant: $v}
                                                else {backend: $b, agent: $a, model: $m, pinned: $p} end))
           | (if $r == "worker" then .worker = $m elif $r == "recon" then .recon = $m else . end)
           | .updated = $u' > "$tmp" 2>/dev/null && jq -e . "$tmp" >/dev/null 2>&1; then
        mv "$tmp" "$STATE_FILE"
    else
        rm -f "$tmp"
        echo "tier-set: failed to write $STATE_FILE" >&2
        return 1
    fi
}

# merge_model <id> -- .model = <id> into settings.local.json, everything
# else in the file untouched (created fresh as {} if absent).
merge_model() {
    mkdir -p "$(dirname "$LOCAL_SETTINGS")" 2>/dev/null
    local base tmp
    base='{}'
    if [ -f "$LOCAL_SETTINGS" ] && jq -e . "$LOCAL_SETTINGS" >/dev/null 2>&1; then
        base="$(cat "$LOCAL_SETTINGS")"
    fi
    tmp=$(mktemp "$LOCAL_SETTINGS.XXXXXX") || return 1
    if printf '%s' "$base" | jq --arg m "$1" '.model = $m' > "$tmp" 2>/dev/null && jq -e . "$tmp" >/dev/null 2>&1; then
        mv "$tmp" "$LOCAL_SETTINGS"
    else
        rm -f "$tmp"
        echo "tier-set: failed to update $LOCAL_SETTINGS" >&2
        return 1
    fi
}

# --- show ------------------------------------------------------------------

show_state() {
    local top worker recon pinned overdrive
    top="$(state_field top)"; worker="$(state_field worker)"; recon="$(state_field recon)"
    pinned="$(state_field pinned)"; overdrive="$(state_field overdrive)"

    if [ -z "$top" ] && [ -z "$worker" ] && [ -z "$recon" ]; then
        echo "no tier bound yet -- run /tier <top> (e.g. /tier opus) to bind one"
    else
        echo "orchestrator (top)   = $top"
        echo "worker / executor    = $worker"
        echo "recon / scout        = $recon"
        echo "backends             = worker=$(tier_role_label "$(tier_role_field "$STATE_FILE" worker backend)" "$(tier_role_field "$STATE_FILE" worker agent)" "$worker") recon=$(tier_role_label "$(tier_role_field "$STATE_FILE" recon backend)" "$(tier_role_field "$STATE_FILE" recon agent)" "$recon") checker=$(tier_role_label "$(tier_role_field "$STATE_FILE" checker backend)" "$(tier_role_field "$STATE_FILE" checker agent)" "$(tier_role_field "$STATE_FILE" checker model)")"
        echo "rebind one role: /tier worker openrouter:<vendor/model> | claude:<alias> | subagent  (same for recon/checker)"
        [ "$pinned" = "true" ] && echo "explicit pin: ON — worker/recon were set manually (tier-set <top> <worker> [<recon>]); a plain /tier <top> clears it."
        [ "$overdrive" = "true" ] && echo "overdrive: ON — the worker cap is LIFTED (executor runs the top model); a plain /tier <top> clears it."
    fi
    echo "1-arg /tier auto-derives worker/recon: worker = one rung down capped at sonnet-class, recon = one below the worker (fable>opus>sonnet>haiku, floored)."
    echo "2/3-arg /tier <top> <worker> [<recon>] pins those bindings explicitly; /tier overdrive lifts the worker cap on the bound top."
    echo "the checker (verifier) rung is derived too: the top capped at opus, so a fable top is graded from opus; oracle still inherits the orchestrator's model. /model is the primary in-session lever for the derived default."
    echo "cheap recon on OpenRouter: /tier recon openrouter  binds $TIER_OPENROUTER_RECON_MODEL on the orca backend (opencode)."
    show_help
}

# The explanation of the command itself. It used to be the body of
# config/claude-commands/tier.md, so every /tier <anything> re-read it;
# now only a bare /tier and /tier help print it, and a binding call prints
# its bound line and nothing else.
show_help() {
    cat <<EOF
/tier overdrive lifts the worker cap so the executor runs the TOP model (recon stays cheap) and keeps it lifted as /model moves the top; it is expensive, says so on every session-start tier line, and a 1-arg /tier <top> clears it.
each role (worker · recon · checker) also carries a backend: orca (a supervised Orca worker terminal, dispatched with orca-dispatch) or subagent (the in-process Agent tool). /tier worker openrouter:z-ai/glm-5.3-flash binds OpenRouter's GLM 5.3 Flash run by opencode on the orca backend, /tier worker claude:sonnet an orca-backed Claude worker, /tier worker subagent puts it back in-process on the derived model; recon and checker take the same specs. /tier recon openrouter (bare spec, no model named) binds the role's own OpenRouter default, for recon the flash-class rung $TIER_OPENROUTER_RECON_MODEL.
a 1-arg /tier <top> resets all three to the defaults: worker orca+claude when the Orca runtime is reachable, else subagent; recon subagent haiku; checker subagent at the derived checker rung (the top capped at opus), so a fable top is graded from opus. An off-ladder top leaves the checker on inherit. With an OpenRouter key in this folder the default worker is the GLM rung on opencode, and every OpenRouter request goes through the in-VM guard, which forces config/provider-policy.json's US/EU provider allowlist; /tier worker claude:sonnet puts the claude rung back.
an openrouter: bind still saves with no credential in this folder -- it names /tier auth openrouter as the next step, which opens a focused Orca tab that gets a key, validates it and starts the guard; with no Orca runtime it prints the same command to run by hand.
a binding applies to NEW spawns immediately (tier-gate reads tier.json at spawn time); /model <top> moves THIS session's own model now.
EOF
}

# --- argument normalisation (claude-orca-2j2) -------------------------------
#
# Exactly one argument containing a comma or whitespace is re-split BEFORE
# anything below looks at $#/$1 -- on commas when any are present (each
# phrase trimmed), else on whitespace. An empty single argument behaves like
# no args (show). config/claude-commands/tier.md passes "$ARGUMENTS" quoted
# so a phrase like "fable, GLM 5.3 flash, GPT-5.6 Luna (high)" arrives here
# whole.
if [ $# -eq 1 ]; then
    _tier_raw="$1"
    if [ -z "$_tier_raw" ]; then
        set --
    else
        case "$_tier_raw" in
            *,*)
                _tier_oldifs="$IFS"
                IFS=','
                set -f; set -- $_tier_raw; set +f
                IFS="$_tier_oldifs"
                _tier_trimmed=()
                for _tier_tok in "$@"; do
                    _tier_tok="$(trim "$_tier_tok")"
                    [ -n "$_tier_tok" ] && _tier_trimmed+=("$_tier_tok")
                done
                set -- "${_tier_trimmed[@]+"${_tier_trimmed[@]}"}"
                ;;
            *[[:space:]]*)
                set -f; set -- $_tier_raw; set +f
                ;;
        esac
    fi
fi

if [ $# -eq 0 ] || [ "${1:-}" = "show" ]; then
    show_state
    exit 0
fi

case "${1:-}" in
    help|-h|--help)
        show_help
        exit 0
        ;;
esac

for _tier_arg in "$@"; do
    case "$_tier_arg" in
        -*)
            echo "tier-set: unrecognized option '$_tier_arg' -- nothing bound" >&2
            exit 1
            ;;
    esac
done

# --- overdrive ---------------------------------------------------------------

if [ $# -eq 1 ] && [ "$1" = "overdrive" ]; then
    [ -x "$DERIVE" ] || { echo "tier-set: tier-derive not found or not executable ($DERIVE) -- cannot derive the trio; nothing bound" >&2; exit 1; }
    top="$(state_field top)"
    if [ -z "$top" ]; then
        echo "tier-set: no top bound yet -- overdrive lifts an existing top; run /tier <top> first; nothing bound" >&2
        exit 1
    fi
    if ! trio=$("$DERIVE" --overdrive "$top" 2>/dev/null); then
        echo "tier-set: top '$top' is off-ladder -- not liftable; bindings left untouched, nothing bound" >&2
        exit 1
    fi
    set -f; set -- $trio; set +f
    W=$2; C=$3   # $1 (the resolved top) is discarded: it is not re-bound
    write_state "$top" "$W" "$C" false true || exit 1
    echo "tier bound (overdrive — worker cap LIFTED)  top=$top  →  worker=$W  recon=$C  — a plain /tier <top> clears overdrive"
    echo "→ applies to NEW spawns (tier-gate reads tier.json at spawn time)."
    exit 0
fi

# --- auth: tier-set auth <provider> -----------------------------------------
#
# Opens a focused Orca tab running scripts/openrouter-auth.sh so sign-in
# happens without leaving the session (plan .claude/plans/openrouter-auth.md
# "Auth happens in a tab"). An unreachable Orca runtime is not an error --
# there is a manual fallback -- so this always exits 0 once the provider
# name itself checks out.
if [ "${1:-}" = "auth" ]; then
    provider="${2:-}"
    if [ "$provider" != "openrouter" ]; then
        echo "tier-set: usage: tier-set auth openrouter" >&2
        exit 1
    fi
    # shellcheck source=lib/orca-orch.sh
    . "$SCRIPT_DIR/lib/orca-orch.sh"
    HELPER="$SCRIPT_DIR/openrouter-auth.sh"
    root="$(orch_root 2>/dev/null)" || root="$PWD"
    if out="$(orca_call terminal create --worktree "path:$root" \
                --title "OpenRouter sign-in" --command "$HELPER" \
                --focus --json)"; then
        echo "tier-set: opened an Orca tab \"OpenRouter sign-in\" — complete sign-in there."
        exit 0
    fi
    err="$(orca_error "$out" 2>/dev/null)"; [ -n "$err" ] || err="Orca runtime unreachable"
    echo "tier-set: could not open an Orca tab ($err) -- run this by hand in any terminal instead:" >&2
    echo "  $HELPER"
    exit 0
fi

# --- one role: tier-set <worker|recon|checker> <spec> -----------------------

# derived_role_model <role> -- the ladder's model for that role, from the
# bound top (overdrive-aware). checker never derives: it inherits.
derived_role_model() {
    local r="$1" top trio ck
    top="$(state_field top)"
    if [ -z "$top" ]; then
        # The checker has a sane answer without a top -- "inherit", what it
        # was before the rung existed -- so only worker/recon insist on one.
        [ "$r" = "checker" ] && { echo inherit; return 0; }
        echo "tier-set: no top bound yet -- run /tier <top> first; nothing bound" >&2
        return 1
    fi
    if [ "$r" = "checker" ]; then
        ck=$("$DERIVE" --checker "$top" 2>/dev/null) || ck=""
        [ -n "$ck" ] || ck=inherit
        echo "$ck"
        return 0
    fi
    if [ "$(state_field overdrive)" = "true" ]; then
        trio=$("$DERIVE" --overdrive "$top" 2>/dev/null) || trio=""
    else
        trio=$("$DERIVE" "$top" 2>/dev/null) || trio=""
    fi
    if [ -z "$trio" ]; then
        echo "tier-set: top '$top' is off-ladder -- no model to derive for '$r'; name one explicitly (e.g. /tier $r claude:sonnet); nothing bound" >&2
        return 1
    fi
    set -f; set -- $trio; set +f
    case "$r" in
        worker) echo "$2" ;;
        recon)  echo "$3" ;;
    esac
}

# --- the OpenRouter model catalogue (claude-orca-2j2) -----------------------

# models_file -- TIER_MODELS_FILE, else <run dir>/openrouter-models.json
# (next to tier.json), else beside STATE_FILE when run_dir can't resolve.
models_file() {
    if [ -n "${TIER_MODELS_FILE:-}" ]; then
        printf '%s\n' "$TIER_MODELS_FILE"
        return 0
    fi
    local d
    d="$(run_dir 2>/dev/null)" || d=""
    if [ -z "$d" ] && [ -n "$STATE_FILE" ]; then
        d="$(dirname "$STATE_FILE")"
    fi
    [ -n "$d" ] || d="."
    printf '%s\n' "$d/openrouter-models.json"
}

# ensure_catalogue <file> -- fetches the catalogue when it is missing or
# older than 24h, unless TIER_MODELS_FETCH=0. A failed fetch (no curl, no
# network, bad JSON) silently keeps whatever is already on disk -- never an
# error, since the caller decides what an absent/stale file means.
ensure_catalogue() {
    local file="$1" now mtime age tmp
    [ "${TIER_MODELS_FETCH:-1}" = "0" ] && return 0
    now=$(date +%s)
    if [ -f "$file" ]; then
        mtime=$(stat -c %Y "$file" 2>/dev/null || stat -f %m "$file" 2>/dev/null || echo 0)
        age=$(( now - mtime ))
        [ "$age" -lt 86400 ] && return 0
    fi
    command -v curl >/dev/null 2>&1 || return 0
    mkdir -p "$(dirname "$file")" 2>/dev/null
    tmp=$(mktemp "$file.XXXXXX" 2>/dev/null) || return 0
    if curl -sf -m 10 "https://openrouter.ai/api/v1/models" -o "$tmp" 2>/dev/null \
          && jq -e . "$tmp" >/dev/null 2>&1; then
        mv "$tmp" "$file"
    else
        rm -f "$tmp"
    fi
    return 0
}

# build_words_json <query> -- lowercase, whitespace-split, each word
# stripped to [a-z0-9], as a JSON array (empty words dropped).
build_words_json() {
    local q="$1"
    # the trailing \n matters: without it, `read` hits EOF on the LAST word
    # (no newline after it) and the while loop's condition fails before its
    # body runs, silently dropping that word.
    printf '%s\n' "$q" | tr 'A-Z' 'a-z' | tr -s '[:space:]' '\n' | while IFS= read -r w; do
        [ -n "$w" ] || continue
        printf '%s' "$w" | tr -cd 'a-z0-9'
        printf '\n'
    done | jq -R -s 'split("\n") | map(select(length > 0))'
}

# catalogue_match <file> <query> -- TSV candidate lines "id\tname\tprompt\t
# completion", every word of <query> a substring of the candidate's
# normalised id+name; a ':'-bearing id (batch/free/exacto variants) is
# excluded unless <query> itself contains ':'.
catalogue_match() {
    local file="$1" query="$2" words_json has_colon=false
    case "$query" in *:*) has_colon=true ;; esac
    words_json="$(build_words_json "$query")"
    [ "$words_json" = "[]" ] && return 0
    jq -r --argjson words "$words_json" --argjson hascolon "$has_colon" '
      def norm: ascii_downcase | gsub("[^a-z0-9]"; "");
      [ .data[]?
        | select($hascolon or ((.id // "") | contains(":") | not))
        | . as $m
        | (($m.id // "") | norm) as $nid
        | (($m.name // "") | norm) as $nname
        | ($nid + $nname) as $hay
        | select( ($words | length) > 0 and ([ $words[] as $w | ($hay | contains($w)) ] | all) )
        | [$m.id, ($m.name // ""), ($m.pricing.prompt // "0"), ($m.pricing.completion // "0")]
      ] | .[] | @tsv
    ' "$file" 2>/dev/null
}

# pick_prefix_id <newline-separated ids> -- the id that is a string prefix of
# every id in the list (itself included), or nothing if there isn't one.
pick_prefix_id() {
    local ids="$1" cand other ok
    while IFS= read -r cand; do
        [ -n "$cand" ] || continue
        ok=true
        while IFS= read -r other; do
            [ -n "$other" ] || continue
            case "$other" in
                "$cand"*) ;;
                *) ok=false ;;
            esac
        done <<<"$ids"
        if [ "$ok" = true ]; then
            printf '%s\n' "$cand"
            return 0
        fi
    done <<<"$ids"
    return 1
}

# catalogue_lookup <query> -- prints the bare (no "openrouter/" prefix)
# matched id on success; on ambiguity or absence, prints an explanation to
# stderr and returns 1. See scripts/tier-set.sh's header / claude-orca-2j2's
# bead for the exact matching/prefix/candidate-listing rules.
catalogue_lookup() {
    local query="$1" file matches count ids chosen
    file="$(models_file)"
    ensure_catalogue "$file"
    if [ ! -s "$file" ]; then
        echo "tier-set: no OpenRouter model catalogue available (set TIER_MODELS_FETCH=1, or provide TIER_MODELS_FILE, or the fetch failed) -- name the vendor/model explicitly instead, e.g. worker openrouter:vendor/model; nothing bound" >&2
        return 1
    fi
    matches="$(catalogue_match "$file" "$query")"
    count=0
    [ -n "$matches" ] && count=$(printf '%s\n' "$matches" | grep -c .)
    if [ "$count" -eq 0 ]; then
        echo "tier-set: no catalogue match for '$query' -- nothing bound" >&2
        return 1
    fi
    if [ "$count" -eq 1 ]; then
        printf '%s\n' "$matches" | cut -f1
        return 0
    fi
    ids="$(printf '%s\n' "$matches" | cut -f1)"
    chosen="$(pick_prefix_id "$ids")"
    if [ -n "$chosen" ]; then
        printf '%s\n' "$chosen"
        return 0
    fi
    {
        echo "tier-set: ambiguous model query '$query' -- candidates:"
        printf '%s\n' "$matches" | head -10 | awk -F'\t' '{printf "  %s  %s  $%s/$%s per M\n", $1, $2, $3, $4}'
        echo "tier-set: nothing bound"
    } >&2
    return 1
}

# resolve_worker_recon_phrase <worker|recon> <name> <positional|role>
# The shared resolver behind both the trio positional form and the per-role
# `tier-set worker|recon <spec>` form -- <name> already has any @effort
# suffix stripped by parse_effort. Prints "<backend>\t<agent>\t<model>" on
# success; an error (unknown/unsafe spec, catalogue ambiguity/absence) goes
# to stderr and this returns 1, nothing bound.
#
# Resolution order (claude-orca-2j2, bead SPEC point 4):
#   a. a Claude alias/id -- backend follows <ctx> (see below)
#   b. an existing explicit spec: openrouter[:.../], claude:, codex:/gemini:,
#      orca, subagent, inherit -- unchanged from the single-role grammar
#   c. a route NAME in $ROUTES_FILE -- its .model, backend orca/opencode
#   d. a phrase containing '/' -- an explicit OpenRouter id (a leading
#      "openrouter/" is optional and normalised in)
#   e. otherwise, an OpenRouter catalogue lookup
#
# <ctx>: "positional" reproduces write_state's own rule for a Claude WORKER
# (orca when tier_orca_reachable, else subagent; recon stays subagent, as it
# always has); "role" is the per-role form's rule -- always subagent+claude,
# regardless of role or Orca reachability (unchanged from the pre-existing
# single-role grammar).
resolve_worker_recon_phrase() {
    local role="$1" name="$2" ctx="$3" b a m rest bare
    case "$name" in
        fable|Fable|FABLE|opus|Opus|OPUS|sonnet|Sonnet|SONNET|haiku|Haiku|HAIKU|claude-*)
            m="$(alias_id "$name")"
            a=claude
            if [ "$ctx" = "positional" ] && [ "$role" = "worker" ]; then
                b=subagent; tier_orca_reachable && b=orca
            else
                b=subagent
            fi
            ;;
        openrouter)
            b=orca; a=opencode; m="$(tier_openrouter_role_default "$role")" ;;
        openrouter:*)
            rest="${name#openrouter:}"
            [ -n "$rest" ] || { echo "tier-set: 'openrouter:' needs a <vendor/model>, e.g. openrouter:qwen/qwen3-coder -- nothing bound" >&2; return 1; }
            b=orca; a=opencode; m="openrouter/$rest" ;;
        claude:*)
            rest="${name#claude:}"
            b=orca; a=claude
            if [ -n "$rest" ]; then m="$(alias_id "$rest")"
            else m="$(derived_role_model "$role")" || return 1; fi ;;
        codex:*|gemini:*)
            a="${name%%:*}"; rest="${name#*:}"
            [ -n "$rest" ] || { echo "tier-set: '$a:' needs a model id -- nothing bound" >&2; return 1; }
            b=orca; m="$rest" ;;
        orca)
            b=orca; a=claude; m="$(derived_role_model "$role")" || return 1 ;;
        subagent)
            b=subagent; a=claude; m="$(derived_role_model "$role")" || return 1 ;;
        inherit)
            b=subagent; a=claude; m=inherit ;;
        *)
            bare=""
            if [ -n "$ROUTES_FILE" ] && [ -f "$ROUTES_FILE" ]; then
                bare="$(jq -r --arg n "$name" '.routes[$n].model // empty' "$ROUTES_FILE" 2>/dev/null)"
            fi
            if [ -n "$bare" ]; then
                b=orca; a=opencode; m="$bare"
            else
                case "$name" in
                    */*)
                        rest="$name"
                        case "$rest" in openrouter/*) rest="${rest#openrouter/}" ;; esac
                        b=orca; a=opencode; m="openrouter/$rest"
                        ;;
                    *)
                        bare="$(catalogue_lookup "$name")" || return 1
                        b=orca; a=opencode; m="openrouter/$bare"
                        ;;
                esac
            fi
            ;;
    esac
    valid_model_ref "$m" || { echo "tier-set: unknown or unsafe model reference for '$role': '$name' -- nothing bound" >&2; return 1; }
    printf '%s\t%s\t%s\n' "$b" "$a" "$m"
}

case "${1:-}" in
    checker)
        role=$1
        if [ $# -lt 2 ]; then
            echo "tier-set: '$role' needs a backend/model spec -- e.g. /tier $role openrouter:qwen/qwen3-coder | claude:sonnet | subagent; nothing bound" >&2
            exit 1
        fi
        spec=$2
        [ $# -gt 2 ] && echo "tier: extra args ignored (dropped: ${*:3})" >&2
        B=subagent; A=claude; M=""; PIN=false; IS_OPENROUTER=false
        case "$spec" in
            openrouter)
                # No model named: the role's own OpenRouter default -- the
                # flash rung for recon, the full-size GLM otherwise.
                B=orca; A=opencode; M="$(tier_openrouter_role_default "$role")"
                PIN=true; IS_OPENROUTER=true ;;
            openrouter:*)
                rest="${spec#openrouter:}"
                [ -n "$rest" ] || { echo "tier-set: 'openrouter:' needs a <vendor/model>, e.g. openrouter:qwen/qwen3-coder -- nothing bound" >&2; exit 1; }
                B=orca; A=opencode; M="openrouter/$rest"; PIN=true; IS_OPENROUTER=true ;;
            claude:*)
                rest="${spec#claude:}"
                B=orca; A=claude
                if [ -n "$rest" ]; then M="$(alias_id "$rest")"; PIN=true
                else M="$(derived_role_model "$role")" || exit 1; fi ;;
            codex:*|gemini:*)
                A="${spec%%:*}"; rest="${spec#*:}"
                [ -n "$rest" ] || { echo "tier-set: '$A:' needs a model id -- nothing bound" >&2; exit 1; }
                B=orca; M="$rest"; PIN=true ;;
            orca)
                B=orca; A=claude; M="$(derived_role_model "$role")" || exit 1 ;;
            subagent)
                B=subagent; A=claude; M="$(derived_role_model "$role")" || exit 1 ;;
            inherit)
                B=subagent; A=claude; M=inherit; PIN=true ;;
            *)
                B=subagent; A=claude; M="$(alias_id "$spec")"; PIN=true ;;
        esac
        valid_model_ref "$M" || { echo "tier-set: unknown or unsafe model reference for '$role': '$spec' -- nothing bound" >&2; exit 1; }
        write_role "$role" "$B" "$A" "$M" "$PIN" || exit 1
        echo "tier role bound  $role = $(tier_role_label "$B" "$A" "$M")"
        if [ "$IS_OPENROUTER" = "true" ] && ! tier_openrouter_ready; then
            echo "→ not authenticated yet -- this binding is saved but cannot run until OpenRouter is set up in this folder."
            echo "→ run  /tier auth openrouter  to open a sign-in tab now."
        fi
        if [ "$B" = "orca" ]; then
            echo "→ applies to NEW spawns: $role slices go through  orca-dispatch  (the Agent tool stays the fallback)."
        else
            echo "→ applies to NEW spawns: $role runs in the Agent tool, tier-gate injects $M at spawn time."
        fi
        exit 0
        ;;
    worker|recon)
        role=$1
        shift
        if [ $# -lt 1 ]; then
            echo "tier-set: '$role' needs a phrase or backend/model spec -- e.g. /tier $role openrouter:qwen/qwen3-coder | claude:sonnet | subagent | glm-flash | luna@high; nothing bound" >&2
            exit 1
        fi
        # A recognised effort word as the 2nd remaining token joins with the
        # 1st into one phrase (the per-role bare-trailing-word form, e.g.
        # "recon luna high"); otherwise it (and anything past it) is just
        # ignored, as extra args always have been here.
        if [ $# -ge 2 ] && valid_effort "$2"; then
            role_spec="$1 $2"
            [ $# -gt 2 ] && echo "tier: extra args ignored (dropped: ${*:3})" >&2
        else
            role_spec="$1"
            [ $# -gt 1 ] && echo "tier: extra args ignored (dropped: ${*:2})" >&2
        fi
        role_out="$(parse_effort "$role_spec")" || exit 1
        role_name="$(printf '%s\n' "$role_out" | sed -n 1p)"
        role_effort="$(printf '%s\n' "$role_out" | sed -n 2p)"
        role_line="$(resolve_worker_recon_phrase "$role" "$role_name" role)" || exit 1
        IFS=$'\t' read -r B A M <<<"$role_line"
        role_note=""
        if [ -n "$role_effort" ] && [ "$A" != "opencode" ]; then
            role_note="tier: effort '$role_effort' applies to OpenRouter roles only -- ignored for $role"
            role_effort=""
        fi
        write_role "$role" "$B" "$A" "$M" true "$role_effort" || exit 1
        echo "tier role bound  $role = $(tier_role_label "$B" "$A" "$M" "$role_effort")"
        [ -n "$role_note" ] && echo "$role_note"
        if [ "$A" = "opencode" ] && ! tier_openrouter_ready; then
            echo "→ not authenticated yet -- this binding is saved but cannot run until OpenRouter is set up in this folder."
            echo "→ run  /tier auth openrouter  to open a sign-in tab now."
        fi
        if [ "$B" = "orca" ]; then
            echo "→ applies to NEW spawns: $role slices go through  orca-dispatch  (the Agent tool stays the fallback)."
        else
            echo "→ applies to NEW spawns: $role runs in the Agent tool, tier-gate injects $M at spawn time."
        fi
        exit 0
        ;;
esac

# --- models: tier-set models [<words>] --------------------------------------

if [ "${1:-}" = "models" ]; then
    shift
    words="$*"
    if [ -z "$words" ]; then
        if [ -f "$ROUTES_FILE" ]; then
            jq -r '.routes | to_entries[] | "\(.key)\t\(.value.model // "")"' "$ROUTES_FILE" 2>/dev/null |
                while IFS=$'\t' read -r rn rm; do
                    [ -n "$rn" ] && echo "route  $rn -> $rm"
                done
        else
            echo "no routes file at $ROUTES_FILE"
        fi
        mfile="$(models_file)"
        if [ -s "$mfile" ]; then
            mcount=$(jq -r '(.data | length) // 0' "$mfile" 2>/dev/null)
            mmtime=$(stat -c %Y "$mfile" 2>/dev/null || stat -f %m "$mfile" 2>/dev/null || echo 0)
            mage=$(( $(date +%s) - mmtime ))
            echo "catalogue: $mcount models, ${mage}s old ($mfile)"
        else
            echo "catalogue: no file at $mfile"
        fi
        exit 0
    fi
    mfile="$(models_file)"
    ensure_catalogue "$mfile"
    if [ ! -s "$mfile" ]; then
        echo "tier-set: no catalogue available at $mfile" >&2
        exit 1
    fi
    matches="$(catalogue_match "$mfile" "$words")"
    if [ -z "$matches" ]; then
        echo "no catalogue match for '$words'"
        exit 0
    fi
    printf '%s\n' "$matches" | awk -F'\t' '{printf "%s  %s  $%s/$%s per M\n", $1, $2, $3, $4}'
    exit 0
fi

# --- 1-arg (auto-derive) or 2/3-arg (explicit pin) --------------------------

if [ $# -eq 1 ]; then
    resolved="$(alias_id "$1")"
    valid_id "$resolved" || { echo "tier-set: unknown subcommand or model id: '$1'" >&2; exit 1; }
    [ -x "$DERIVE" ] || { echo "tier-set: tier-derive not found or not executable ($DERIVE) -- cannot derive the trio; nothing bound" >&2; exit 1; }
    R=$resolved
    if trio=$("$DERIVE" "$R" 2>/dev/null); then
        set -f; set -- $trio; set +f
        R=$1; W=$2; C=$3
    else
        W=$R; C=$R
        echo "tier: top '$R' is off-ladder — worker/recon set to the same model (not derivable)" >&2
    fi
    write_state "$R" "$W" "$C" false false true || exit 1
    merge_model "$R" || exit 1
    if [ "$TIER_EFFECTIVE_WORKER" != "$W" ]; then
        echo "tier bound  top=$R  →  worker=$TIER_EFFECTIVE_WORKER (opencode)  recon=$C  (this folder has an OpenRouter key, so the worker default is the GLM rung; /tier help explains)"
    else
        echo "tier bound  top=$R  →  worker=$W  recon=$C  (worker/recon derived from the top)"
    fi
    echo "→ applies to NEW spawns (tier-gate reads tier.json at spawn time); /model $R moves THIS session now."
    exit 0
fi

# --- 2/3-arg positional pin: each arg is now a PHRASE (claude-orca-2j2) ----

top_out="$(parse_effort "$1")" || exit 1
top_name="$(printf '%s\n' "$top_out" | sed -n 1p)"
top_effort="$(printf '%s\n' "$top_out" | sed -n 2p)"
R="$(alias_id "$top_name")"
valid_id "$R" || { echo "tier-set: unknown or unsafe top model id: '$1' -- nothing bound" >&2; exit 1; }
top_note=""
[ -n "$top_effort" ] && top_note="tier: effort '$top_effort' applies to OpenRouter roles only -- ignored for top"

worker_out="$(parse_effort "$2")" || exit 1
worker_name="$(printf '%s\n' "$worker_out" | sed -n 1p)"
worker_effort="$(printf '%s\n' "$worker_out" | sed -n 2p)"
worker_line="$(resolve_worker_recon_phrase worker "$worker_name" positional)" || exit 1
IFS=$'\t' read -r WB WA WM <<<"$worker_line"
worker_note=""
if [ -n "$worker_effort" ] && [ "$WA" != "opencode" ]; then
    worker_note="tier: effort '$worker_effort' applies to OpenRouter roles only -- ignored for worker"
    worker_effort=""
fi

if [ $# -ge 3 ]; then
    [ $# -gt 3 ] && echo "tier: extra args ignored (dropped: ${*:4})" >&2
    recon_out="$(parse_effort "$3")" || exit 1
    recon_name="$(printf '%s\n' "$recon_out" | sed -n 1p)"
    recon_effort="$(printf '%s\n' "$recon_out" | sed -n 2p)"
    recon_line="$(resolve_worker_recon_phrase recon "$recon_name" positional)" || exit 1
    IFS=$'\t' read -r CB CA CM <<<"$recon_line"
    recon_note=""
    if [ -n "$recon_effort" ] && [ "$CA" != "opencode" ]; then
        recon_note="tier: effort '$recon_effort' applies to OpenRouter roles only -- ignored for recon"
        recon_effort=""
    fi
else
    # 2-arg form: a 2-level config -- recon shares the worker binding whole.
    CB="$WB"; CA="$WA"; CM="$WM"; recon_effort="$worker_effort"; recon_note=""
fi

write_state_v3 "$R" "$WB" "$WA" "$WM" "$worker_effort" "$CB" "$CA" "$CM" "$recon_effort" true false || exit 1
merge_model "$R" || exit 1
echo "tier bound (explicit, pinned)  top=$R  worker=$(tier_role_label "$WB" "$WA" "$WM" "$worker_effort")  recon=$(tier_role_label "$CB" "$CA" "$CM" "$recon_effort")  — a plain /tier <top> clears the pin"
[ -n "$top_note" ] && echo "$top_note"
[ -n "$worker_note" ] && echo "$worker_note"
[ -n "$recon_note" ] && echo "$recon_note"
echo "→ applies to NEW spawns (tier-gate reads tier.json at spawn time); /model $R moves THIS session now."
exit 0
